namespace BlazorNotifications.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.Add(new Notification(_nextId++, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-10)));
        _notifications.Add(new Notification(_nextId++, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-5)));
        _notifications.Add(new Notification(_nextId++, "New feature available: Dark Mode.", DateTime.UtcNow.AddMinutes(-2)));
    }

    public List<Notification> GetNotifications()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    public List<Notification> GetNotificationsSince(int lastId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastId).ToList();
        }
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Called internally to generate fake data on each poll.
    /// </summary>
    public void SimulateIncoming()
    {
        if (Random.Shared.Next(0, 3) == 0) // ~33% chance each poll
        {
            lock (_lock)
            {
                var messages = new[]
                {
                    "Someone liked your post.",
                    "You have a new follower.",
                    "Server maintenance scheduled.",
                    "Your report is ready.",
                    "New comment on your article."
                };
                var msg = messages[Random.Shared.Next(messages.Length)];
                _notifications.Add(new Notification(_nextId++, msg, DateTime.UtcNow));
            }
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@using BlazorNotifications.Services
@inject NotificationService NotificationSvc
@inject PersistentComponentState ApplicationState

<PageTitle>Notifications</PageTitle>

<h1>Notifications</h1>

<span class="badge bg-primary fs-6 mb-3">@notifications.Count</span>

<ul class="list-group">
    @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
    {
        <li class="list-group-item d-flex justify-content-between align-items-center">
            @n.Message
            <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
        </li>
    }
</ul>

@code {
    private List<Notification> notifications = new();
    private CancellationTokenSource? _cts;
    private PersistingComponentStateSubscription _persistingSubscription;

    protected override void OnInitialized()
    {
        // Subscribe to persist state so SSR data survives into interactive mode
        _persistingSubscription = ApplicationState.RegisterOnPersisting(PersistNotifications);

        // Try to restore persisted state (interactive reconnect scenario)
        if (ApplicationState.TryTakeFromJson<List<Notification>>("notifications", out var restored))
        {
            notifications = restored!;
        }
        else
        {
            // First render (SSR): load from service
            notifications = NotificationSvc.GetNotifications();
        }
    }

    private Task PersistNotifications()
    {
        ApplicationState.PersistAsJson("notifications", notifications);
        return Task.CompletedTask;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender only fires when interactive — safe to start polling
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        // Determine the highest ID we already have to avoid duplicates
        var lastId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;

        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }

            // Simulate new data arriving in the service
            NotificationSvc.SimulateIncoming();

            var newItems = NotificationSvc.GetNotificationsSince(lastId);
            if (newItems.Count > 0)
            {
                notifications.AddRange(newItems);
                lastId = newItems.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _persistingSubscription.Dispose();
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

